/** 绿茵视界公共及社区模块；本人负责，AI辅助编写。 */ use yii\helpers\Html;use yii\widgets\ActiveForm;$this->title=$post->title.' · 绿茵视界'; ?><span class="eyebrow">FAN DISCUSSION</span><h1><?= Html::encode($post->title) ?></h1><p class="meta"><?= Html::encode($post->author->username) ?> · <?= Html::encode($post->created_at) ?></p><article class="card prose"><?= Html::encode($post->content) ?></article><h2>球迷评论</h2><?php foreach($comments as $c): ?><article class="card comment"><div class="meta"><?= Html::encode($c->author->username) ?> · <?= Html::encode($c->created_at) ?><?php if($c->parent_id): ?> · 回复 #<?= (int)$c->parent_id ?><?php endif ?></div><p class="prose"><?= Html::encode($c->content) ?></p><?= Html::a('回复',['view','id'=>$post->id,'reply_to'=>$c->id,'#'=>'comment-form']) ?></article><?php endforeach ?><?= \yii\widgets\LinkPager::widget(['pagination'=>$pages]) ?><?php if(Yii::$app->user->isGuest): ?><p><?= Html::a('登录后参与讨论',['site/login'],['class'=>'button']) ?></p><?php else: ?><section id="comment-form"><h2>留下你的看法</h2><?php $f=ActiveForm::begin(['action'=>['comment','id'=>$post->id],'enableClientValidation'=>false]) ?><?= $f->field($model,'content')->textarea() ?><?= $f->field($model,'parent_id')->hiddenInput(['value'=>is_scalar(Yii::$app->request->get('reply_to'))?Yii::$app->request->get('reply_to'):null])->label(false) ?><button>提交评论</button><?php ActiveForm::end() ?></section><?php endif ?>
